TArray<FOWAbility> UOWElements::GetAllAbilities(const UOWWorld* World)
{
	TArray<FOWAbility> Out;
	OWModelRead::Each(World, "ability", [&Out](const OnlyWorlds::OWJsonValue& Body) { OWFromJson(Body, Out.AddDefaulted_GetRef()); });
	return Out;
}

bool UOWElements::FindAbility(const UOWWorld* World, const FString& Id, FOWAbility& Ability)
{
	const OnlyWorlds::OWJsonValue* Body = OWModelRead::Find(World, Id, "ability");
	if (!Body) return false;
	Ability = FOWAbility();
	OWFromJson(*Body, Ability);
	return true;
}

